import {bank} from './data.js';
export const normalize=s=>String(s).normalize('NFKC').toLowerCase().replace(/[.,!?;:'"()\[\]{}]/g,'').replace(/[-–—]/g,' ').trim().replace(/\s+/g,' ');
export const correct=(q,s)=>[q.answer,...q.alternatives].some(a=>normalize(a)===normalize(s));
export const empty=()=>({version:1,events:[],sessions:[],concepts:{}});
export function record(state,session){const now=Date.now();state.sessions.push({id:session.id,date:now,name:session.name,count:session.results.length,correct:session.results.filter(r=>r.first).length,kind:session.kind});for(const r of session.results){const q=bank.find(q=>q.id===r.qid);if(!q)continue;state.events.push({...r,topic:q.topic,concept:q.concept,date:now,kind:session.kind});if(session.kind==='sort')continue;let k=`${q.topic}:${q.concept}`,c=state.concepts[k]||{streak:0,due:now,last:0};if(r.first&&!r.assisted&&r.eventual){if(now-c.last>20*60*60*1000){c.streak++;c.last=now}c.due=now+[1,3,7,14,30][Math.min(Math.max(c.streak-1,0),4)]*86400000;}else{c.streak=0;c.due=now+10*60000;}state.concepts[k]=c;}return state;}
export function validateBackup(s){if(!s||s.version!==1||!Array.isArray(s.events)||!Array.isArray(s.sessions)||!s.concepts||typeof s.concepts!=='object'||Array.isArray(s.concepts))throw Error('This is not an Anatomy Study Studio backup.');if(s.events.length>100000||s.sessions.length>10000)throw Error('Backup is too large.');for(const e of s.events){if(!bank.some(q=>q.id===e.qid)||!['recall','sort'].includes(e.kind)||!Number.isFinite(e.date)||typeof e.first!=='boolean'||typeof e.eventual!=='boolean'||typeof e.assisted!=='boolean'||typeof e.answer!=='string')throw Error('Backup contains an invalid answer record.');}for(const h of s.sessions){if(typeof h.id!=='string'||typeof h.name!=='string'||!Number.isFinite(h.date)||!Number.isInteger(h.count)||h.count<0||!Number.isInteger(h.correct)||h.correct<0||h.correct>h.count||!['recall','sort'].includes(h.kind))throw Error('Backup contains an invalid session.');}for(const [k,c] of Object.entries(s.concepts)){if(!bank.some(q=>`${q.topic}:${q.concept}`===k)||!Number.isInteger(c.streak)||c.streak<0||!Number.isFinite(c.due)||!Number.isFinite(c.last))throw Error('Backup contains an invalid review schedule.');}return s;}
